import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Hotkeys & Gestures","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Global Hotkeys Cheat Sheet","slug":"_1-global-hotkeys-cheat-sheet","link":"#_1-global-hotkeys-cheat-sheet","children":[{"level":3,"title":"Empty Inline Search in File Dialogs","slug":"empty-inline-search-in-file-dialogs","link":"#empty-inline-search-in-file-dialogs","children":[]},{"level":3,"title":"Summoning and Focus Handover in the Inline Window","slug":"summoning-and-focus-handover-in-the-inline-window","link":"#summoning-and-focus-handover-in-the-inline-window","children":[]}]},{"level":2,"title":"2. Search Box Icon & Mouse Gestures","slug":"_2-search-box-icon-mouse-gestures","link":"#_2-search-box-icon-mouse-gestures","children":[{"level":3,"title":"Quick Window Icon Gestures","slug":"quick-window-icon-gestures","link":"#quick-window-icon-gestures","children":[]},{"level":3,"title":"Inline and Full Window Icons","slug":"inline-and-full-window-icons","link":"#inline-and-full-window-icons","children":[]},{"level":3,"title":"Search Box Gestures (Quick Window)","slug":"search-box-gestures-quick-window","link":"#search-box-gestures-quick-window","children":[]},{"level":3,"title":"System Tray Icon","slug":"system-tray-icon","link":"#system-tray-icon","children":[]}]},{"level":2,"title":"3. Quick Navigation (Mouse Triggers)","slug":"_3-quick-navigation-mouse-triggers","link":"#_3-quick-navigation-mouse-triggers","children":[{"level":3,"title":"Triggering Environments","slug":"triggering-environments","link":"#triggering-environments","children":[]},{"level":3,"title":"Cascading Menu Structure","slug":"cascading-menu-structure","link":"#cascading-menu-structure","children":[]}]},{"level":2,"title":"4. Hardcoded Core Keys (Non-configurable)","slug":"_4-hardcoded-core-keys-non-configurable","link":"#_4-hardcoded-core-keys-non-configurable","children":[]},{"level":2,"title":"5. Plugin Action Hotkeys & Process Blacklist","slug":"_5-plugin-action-hotkeys-process-blacklist","link":"#_5-plugin-action-hotkeys-process-blacklist","children":[{"level":3,"title":"Plugin Action Hotkeys","slug":"plugin-action-hotkeys","link":"#plugin-action-hotkeys","children":[]},{"level":3,"title":"Process Blacklist & Fullscreen Bypass","slug":"process-blacklist-fullscreen-bypass","link":"#process-blacklist-fullscreen-bypass","children":[]}]}],"relativePath":"user-guide/hotkeys.md","filePath":"user-guide/hotkeys.md","lastUpdated":1791112464000}`),a={name:`user-guide/hotkeys.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="hotkeys-gestures" tabindex="-1">Hotkeys &amp; Gestures <a class="header-anchor" href="#hotkeys-gestures" aria-label="Permalink to “Hotkeys &amp; Gestures”">​</a></h1><p>Lertaro embraces a keyboard-first interaction philosophy while offering rich mouse gestures and quick cascading navigation. Except for non-configurable core keys, all global and in-app hotkeys can be customized under <a href="./settings/hotkeys-page.html"><strong>Settings → Hotkeys</strong></a>.</p><h2 id="_1-global-hotkeys-cheat-sheet" tabindex="-1">1. Global Hotkeys Cheat Sheet <a class="header-anchor" href="#_1-global-hotkeys-cheat-sheet" aria-label="Permalink to “1. Global Hotkeys Cheat Sheet”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Default Hotkey</th><th style="text-align:left;">Description &amp; Interaction Details</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Toggle Quick Window</strong></td><td style="text-align:left;">Double-tap <code>Ctrl</code></td><td style="text-align:left;">Can be set to a double-tap mode or standard key combinations (e.g. <code>Alt+Space</code>). A double-tap is two presses of the <strong>same</strong> modifier key released <strong>100–300 ms</strong> apart — left and right <code>Ctrl</code> are different keys, and any other key pressed in between restarts the count. In the double-tap form the modifier itself is never swallowed, so ordinary <code>Ctrl</code>+<code>C</code> style shortcuts keep working. When <strong>Open full panel by default</strong> is enabled, this shortcut opens the Full Window instead: it is brought to the foreground once when first shown, refocused when visible but inactive, and when already active a repeat press returns to the Quick Window by default (or closes outright when <strong>Close Full Window on Repeat Hotkey</strong> is enabled). It is not automatically kept topmost.</td></tr><tr><td style="text-align:left;"><strong>Quick Jump</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">Jumps file dialogs directly to the directory most recently browsed in Explorer, a supported file manager, or a file dialog.</td></tr><tr><td style="text-align:left;"><strong>Quick Navigation Menu</strong></td><td style="text-align:left;">No default</td><td style="text-align:left;">An optional global shortcut opens the cascading Quick Navigation menu. From the desktop or an ordinary app it uses desktop context; in File Explorer and native file dialogs it uses the active window context. File managers and file dialogs remain allowed even when ordinary foreground protections suppress global hotkeys.</td></tr><tr><td style="text-align:left;"><strong>Select Next Item</strong></td><td style="text-align:left;"><code>Ctrl+N</code> or <code>↓</code></td><td style="text-align:left;">Moves highlight down. Navigates across groups in the Quick Panel. In Quick Launch, the arrow keys follow the visible grid; <strong>←</strong> and <strong>→</strong> follow the reading order across row boundaries, while <strong>↑</strong> and <strong>↓</strong> keep the current column and only move between adjacent rows, stopping where the target row has no item in that column. When Quick Launch is visible with an empty query, <code>Ctrl+N</code> cycles to the next data source and wraps at the end.</td></tr><tr><td style="text-align:left;"><strong>Select Previous Item</strong></td><td style="text-align:left;"><code>Ctrl+P</code> or <code>↑</code></td><td style="text-align:left;">Moves highlight up. Navigates across groups in the Quick Panel. In Quick Launch, the arrow keys follow the visible grid; <strong>←</strong> and <strong>→</strong> follow the reading order across row boundaries, while <strong>↑</strong> and <strong>↓</strong> keep the current column and only move between adjacent rows, stopping where the target row has no item in that column. When Quick Launch is visible with an empty query, <code>Ctrl+P</code> cycles to the previous data source and wraps at the beginning.</td></tr><tr><td style="text-align:left;"><strong>Jump to Results 1–9</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">Modifier is customizable. Number badges appear next to visible items for instant activation. The number means the Nth selectable row <strong>from the first visible row</strong>, so the badges renumber as you scroll; <code>0</code> is not bound. The Quick Launch panel is the exception — it binds <code>1</code>–<code>9</code>, <code>0</code> and <code>A</code>–<code>Z</code> for up to 36 tiles.</td></tr><tr><td style="text-align:left;"><strong>Open Action Menu</strong></td><td style="text-align:left;"><code>Ctrl+O</code> or <code>→</code></td><td style="text-align:left;">Expands the context action menu (copy path, properties, run as admin, file operations, etc.). Works in the Quick Window and in the inline card <strong>outside</strong> file dialogs; the Full Window opens the same menu with right-click or the <code>Apps</code> key (<code>Shift+F10</code>) instead.</td></tr><tr><td style="text-align:left;"><strong>Autocomplete from Selection</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">Fills the search box with the selected item&#39;s name or full path for secondary refinement.</td></tr><tr><td style="text-align:left;"><strong>QuickLook Instant Preview</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">Opens or closes the side preview panel (images, documents, audio/video playback, folder trees). Available in the Quick and Full Windows and the Quick Panel, not in the inline card; middle-clicking a previewable row toggles the same panel.</td></tr><tr><td style="text-align:left;"><strong>Previous Search Term</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">Steps backward through recent search query history.</td></tr><tr><td style="text-align:left;"><strong>Next Search Term</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">Steps forward through recent search query history.</td></tr><tr><td style="text-align:left;"><strong>Delete Search History Term</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">Removes the currently displayed keyword from search history.</td></tr><tr><td style="text-align:left;"><strong>Open Full Window</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">Opens the full-sized main search window, carrying over the current query.</td></tr><tr><td style="text-align:left;"><strong>Open LocalSend Window</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">Opens the LocalSend wireless LAN transfer window to quickly send files or text to other devices.</td></tr><tr><td style="text-align:left;"><strong>Pin Window (Keep Visible)</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">Temporarily locks the window open when losing focus (ideal for pasting multi-part queries).</td></tr><tr><td style="text-align:left;"><strong>Toggle Quick Panel</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">Docks the quick panel beside the current active window for recent files, favorites, and workspaces.</td></tr></tbody></table><h3 id="empty-inline-search-in-file-dialogs" tabindex="-1">Empty Inline Search in File Dialogs <a class="header-anchor" href="#empty-inline-search-in-file-dialogs" aria-label="Permalink to “Empty Inline Search in File Dialogs”">​</a></h3><p>When an inline search box is embedded in a native file dialog and the query is empty, the list shows the <strong>Previous Directory</strong> group first. If <strong>Show Currently Open Folders in Inline Search</strong> is enabled, it also shows a <strong>Currently Open Folders</strong> group collected from supported file managers, deliberately including the folder the dialog itself is in; duplicate paths are removed, empty groups stay hidden, and group headers do not receive shortcut badges. The setting is enabled by default and can be changed under <a href="./settings/general.html"><strong>Settings → General → System</strong></a>. This behavior applies only to inline search in file dialogs; Quick and Full Windows are unchanged.</p><h3 id="summoning-and-focus-handover-in-the-inline-window" tabindex="-1">Summoning and Focus Handover in the Inline Window <a class="header-anchor" href="#summoning-and-focus-handover-in-the-inline-window" aria-label="Permalink to “Summoning and Focus Handover in the Inline Window”">​</a></h3><p>A card docked in a native file dialog deliberately <strong>does not steal the keyboard</strong>: the dialog keeps focus, so you keep typing into its own file-name field while the card mirrors the query. The gestures that move the caret are:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Gesture</th><th style="text-align:left;">Effect</th><th style="text-align:left;">Conditions</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Type a letter or digit</strong></td><td style="text-align:left;">Summons the card and carries that first character into the search box; further keystrokes keep flowing in</td><td style="text-align:left;">Real keystrokes only — synthesized input from automation tools is passed through untouched, and nothing is captured while a context or system menu is open</td></tr><tr><td style="text-align:left;"><strong>Double-tap <code>Ctrl</code></strong> (or your configured summon hotkey)</td><td style="text-align:left;">Puts the caret in the card&#39;s own search box. When the box already has the caret and the query is empty, it instead clears the query and hands focus back to the dialog&#39;s field, keeping the card open</td><td style="text-align:left;">The same hotkey as everywhere else, so rebinding it under <a href="./settings/hotkeys-page.html"><strong>Settings → Hotkeys</strong></a> moves this too. A file dialog stays eligible even when a blacklist or fullscreen would normally silence global hotkeys</td></tr><tr><td style="text-align:left;"><strong><code>Escape</code></strong></td><td style="text-align:left;">While the <strong>dialog</strong> holds the keyboard, the card closes. While the <strong>card</strong> holds it, the query is cleared and focus returns to the dialog (in a file dialog) or the card closes (docked over a plain Explorer window)</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong><code>Backspace</code></strong> on an empty box</td><td style="text-align:left;">Leaves the search exactly like <code>Escape</code></td><td style="text-align:left;">Only when the card has the caret; while the dialog holds the keyboard the key only edits the card&#39;s query</td></tr><tr><td style="text-align:left;"><strong><code>Enter</code></strong> on an empty box</td><td style="text-align:left;">Leaves the search like <code>Escape</code></td><td style="text-align:left;">Only when the card has the caret — while the dialog holds the keyboard, <code>Enter</code> opens the highlighted browsing row</td></tr><tr><td style="text-align:left;"><strong><code>Tab</code></strong></td><td style="text-align:left;">Always stays the dialog&#39;s own control traversal, so reach the card with the summon hotkey instead</td><td style="text-align:left;"></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Inside a file dialog the action menu is unavailable for the card (<code>Ctrl+O</code>, <code>→</code> and right-click do nothing there), and <code>Alt+P</code> preview is not offered either. Mouse still works on the rows: <strong>left-click</strong> opens the highlighted result, <strong><code>Ctrl</code>+click</strong> opens it as administrator, a row can be <strong>dragged out</strong> into the dialog, and simply <strong>hovering</strong> moves the selection — which the host file manager mirrors.</p></div><h2 id="_2-search-box-icon-mouse-gestures" tabindex="-1">2. Search Box Icon &amp; Mouse Gestures <a class="header-anchor" href="#_2-search-box-icon-mouse-gestures" aria-label="Permalink to “2. Search Box Icon &amp; Mouse Gestures”">​</a></h2><p>Besides branding, the small logo inside the search box also provides several quick mouse gestures:</p><h3 id="quick-window-icon-gestures" tabindex="-1">Quick Window Icon Gestures <a class="header-anchor" href="#quick-window-icon-gestures" aria-label="Permalink to “Quick Window Icon Gestures”">​</a></h3><ul><li><strong>Left-click</strong>: Pops up the main context menu at the cursor (the same menu as the tray icon: Show Full Window, Send to other devices, Disable/Enable Hotkeys, Settings, About, Clean Exit, Exit). &quot;Show Full Window&quot; carries over your active query.</li><li><strong>Left-click &amp; Drag</strong>: Drags the search bar to reposition it. <strong>Holding <code>Ctrl</code> while dragging</strong> locks movement strictly to the <strong>vertical axis</strong>, keeping horizontal alignment intact.</li><li><strong>Right-click</strong>: Instantly resets the Quick Window back to its default centered screen position without altering configured dimensions.</li><li><strong>Middle-click</strong>: Toggles the &quot;Pin Window&quot; state. The logo illuminates while pinned.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Coordinates remembered for the Quick Window are <strong>proportional relative coordinates</strong> on that specific display. When invoked on another monitor with different resolutions or DPI scalings, Lertaro scales position automatically without escaping visible bounds.</p></div><h3 id="inline-and-full-window-icons" tabindex="-1">Inline and Full Window Icons <a class="header-anchor" href="#inline-and-full-window-icons" aria-label="Permalink to “Inline and Full Window Icons”">​</a></h3><ul><li><strong>Inline Window</strong>: When embedded in native file dialogs (Open/Save/Browse), left-clicking the logo triggers the <a href="#_3-quick-navigation-mouse-triggers"><strong>Quick Navigation</strong></a> cascading menu; disabled in ordinary Explorer windows. Dragging the logo moves the card itself, and the offset is re-applied on every later dock.</li><li><strong>Full Window</strong>: Left-clicking the logo opens the context menu; <strong>Open Full Window</strong> is hidden there because the window is already open. Middle-clicking toggles the window&#39;s pinned state.</li></ul><h3 id="search-box-gestures-quick-window" tabindex="-1">Search Box Gestures (Quick Window) <a class="header-anchor" href="#search-box-gestures-quick-window" aria-label="Permalink to “Search Box Gestures (Quick Window)”">​</a></h3><ul><li><strong>Mouse wheel over the box</strong>: Steps backward/forward through recent search terms — the same navigation as <code>Alt+Up</code> / <code>Alt+Down</code>, without lifting your hand from the mouse.</li><li><strong>Middle-click on the box</strong>: Deletes the history entry currently shown. This gesture is hardcoded and is not the configurable <code>Ctrl+Delete</code> binding.</li><li><strong>Typing at any time</strong> ends the history session, so the next wheel notch starts again from your current query. History does not wrap: the oldest term stops there, and the newest returns the query you started from.</li></ul><h3 id="system-tray-icon" tabindex="-1">System Tray Icon <a class="header-anchor" href="#system-tray-icon" aria-label="Permalink to “System Tray Icon”">​</a></h3><ul><li><strong>Left-click</strong>: Toggles the Quick Window, exactly like the summon hotkey.</li><li><strong>Right-click</strong> (or a second click, since no double-click handler exists): Opens the menu at the cursor — Show Main Window, Send to other devices (only while LocalSend is enabled), Disable/Enable Hotkeys, Settings, About, Clean Exit (only when Lertaro is the only running process) and Exit.</li><li><strong>Hide System Tray Icon</strong> (<a href="./settings/general.html"><strong>Settings → General → System</strong></a>) removes the icon but never the in-window logo menu. While hotkeys are disabled from that menu, the icon is forced back on so you cannot lock yourself out.</li></ul><h2 id="_3-quick-navigation-mouse-triggers" tabindex="-1">3. Quick Navigation (Mouse Triggers) <a class="header-anchor" href="#_3-quick-navigation-mouse-triggers" aria-label="Permalink to “3. Quick Navigation (Mouse Triggers)”">​</a></h2><p>Quick Navigation lets you access frequently used directories and recent files with mouse clicks alone without typing.</p><p>You can also assign an optional global keyboard shortcut under <a href="./settings/hotkeys-page.html"><strong>Settings → Hotkeys</strong></a>. From the desktop or an ordinary app it opens the menu in desktop context; in File Explorer and native file dialogs it uses the active window context.</p><h3 id="triggering-environments" tabindex="-1">Triggering Environments <a class="header-anchor" href="#triggering-environments" aria-label="Permalink to “Triggering Environments”">​</a></h3><ul><li><strong>Desktop Blank Area</strong>: Middle-click (or optional double-left-click) to open the menu. Clicking a folder or file opens it directly.</li><li><strong>File Explorer</strong>: Middle-click empty areas in File Explorer; clicking an item navigates the current window directly to that folder.</li><li><strong>Third-party File Managers</strong>: Middle-click file list areas in Directory Opus, Total Commander, XYplorer, Files, and One Commander (see <a href="./file-manager-support.html"><strong>Supported File Managers</strong></a>).</li><li><strong>File Dialogs</strong>: Middle-click or click the embedded logo inside Open/Save/Browse dialogs to jump to the target folder without accidentally triggering confirmation.</li></ul><h3 id="cascading-menu-structure" tabindex="-1">Cascading Menu Structure <a class="header-anchor" href="#cascading-menu-structure" aria-label="Permalink to “Cascading Menu Structure”">​</a></h3><p>Powered by the <strong>Folder Cascader</strong> plugin:</p><ol><li><strong>Currently Open Folders</strong>: Aggregates and deduplicates active folders from all open file managers.</li><li><strong>Favorites &amp; History</strong>: Lists starred folders, files, and recent visit histories.</li><li><strong>Custom Categories</strong>: Configure nested submenus under <strong>Settings → Plugins → Folder Cascader</strong> (e.g. <code>Work/ProjectA</code>).</li><li><strong>Quick Add Folder (<code>+</code> Button)</strong>: Every submenu header features a small <code>+</code> button to save the currently browsed directory directly into that category.</li></ol><h2 id="_4-hardcoded-core-keys-non-configurable" tabindex="-1">4. Hardcoded Core Keys (Non-configurable) <a class="header-anchor" href="#_4-hardcoded-core-keys-non-configurable" aria-label="Permalink to “4. Hardcoded Core Keys (Non-configurable)”">​</a></h2><p>To ensure consistent and deterministic interaction, the following keys behave identically across all configurations:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Context</th><th style="text-align:left;">Standard Behavior</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Result List</td><td style="text-align:left;">Opens the selected item (file, folder, app, or action). In the Full Window it opens <strong>every</strong> selected row. On an empty inline search box it leaves the search instead — there is no top match to open.</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">Result List</td><td style="text-align:left;">Reveals and selects the item in Windows File Explorer.</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">Result List</td><td style="text-align:left;">Launches the selected item with administrative privileges.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Quick Window</td><td style="text-align:left;">Hides the window. It never empties the box in that press — the query is kept or dropped by <strong>Keep search box content after closing</strong> instead.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Full Window</td><td style="text-align:left;">Clears the query and refocuses the box; closes the window when the box is already empty, or straight away when <strong>Keep search box content after closing</strong> is on (so you never press it twice for nothing).</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Inline card</td><td style="text-align:left;">See <strong>Summoning and Focus Handover in the Inline Window</strong> above: it closes the card while the dialog holds the keyboard, and hands focus back while the card holds it.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Action Menu</td><td style="text-align:left;">One press per level: clears the action filter, then steps back out of the submenu, then leaves the menu and restores the original query.</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">Action Menu</td><td style="text-align:left;">Exits the action menu back to the search list when filter text is empty.</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> Arrow Keys</td><td style="text-align:left;">Action Menu</td><td style="text-align:left;">Left arrow navigates back to parent menu; right arrow enters submenus. <code>Tab</code> enters a submenu too, unless you have bound it to the next/previous-item hotkey.</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">Inline card</td><td style="text-align:left;">Swallowed so focus cannot leave the search box, while <code>Tab</code> inside the dialog itself keeps traversing its own controls as usual.</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">Action Menu</td><td style="text-align:left;">Enters the highlighted submenu — unless you have bound <code>Tab</code> to the next/previous-item hotkey, which wins.</td></tr><tr><td style="text-align:left;"><code>Apps</code> / <code>Shift+F10</code></td><td style="text-align:left;">Full Window</td><td style="text-align:left;">Opens the action menu for the current selection, exactly like right-click.</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">All Lertaro Windows</td><td style="text-align:left;">Suppressed to prevent triggering system titlebar menus on borderless windows.</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">Full / Settings Windows</td><td style="text-align:left;">Closes window normally; suppressed on Quick, Inline, Quick Panel, Preview, LocalSend and in-app dialog windows.</td></tr></tbody></table><h2 id="_5-plugin-action-hotkeys-process-blacklist" tabindex="-1">5. Plugin Action Hotkeys &amp; Process Blacklist <a class="header-anchor" href="#_5-plugin-action-hotkeys-process-blacklist" aria-label="Permalink to “5. Plugin Action Hotkeys &amp; Process Blacklist”">​</a></h2><h3 id="plugin-action-hotkeys" tabindex="-1">Plugin Action Hotkeys <a class="header-anchor" href="#plugin-action-hotkeys" aria-label="Permalink to “Plugin Action Hotkeys”">​</a></h3><p>Built-in file actions ship with these defaults: Cut <code>Ctrl+X</code>, Copy File <code>Ctrl+C</code>, Paste <code>Ctrl+V</code>, Delete <code>Delete</code>, Permanent Delete <code>Shift+Delete</code>, Copy Path <code>Ctrl+Shift+C</code>, Copy Name <code>Shift+C</code>, Reveal in Explorer <code>Ctrl+Enter</code>, Run as Administrator <code>Ctrl+Shift+Enter</code>.</p><p>Two guards make the destructive keys safe under a search box. A chord only reaches an action when the search box has <strong>no text selected</strong>, so <code>Ctrl+X</code> / <code>Ctrl+C</code> / <code>Ctrl+V</code> still cut, copy and paste your query as usual. A bare key like <code>Delete</code> only reaches an action when the caret is <strong>already at the end</strong> of the query, where it has no character left to delete; anywhere else in the text it stays a typing key. And both delete actions go through the shell&#39;s own <code>IFileOperation</code>, so the native &quot;move to Recycle Bin?&quot; / &quot;permanently delete?&quot; prompt still stands between the key and the files. Rebind or clear any of them under <strong>Settings → Hotkeys → Plugin Actions</strong>.</p><h3 id="process-blacklist-fullscreen-bypass" tabindex="-1">Process Blacklist &amp; Fullscreen Bypass <a class="header-anchor" href="#process-blacklist-fullscreen-bypass" aria-label="Permalink to “Process Blacklist &amp; Fullscreen Bypass”">​</a></h3><ul><li><strong>Automatic Fullscreen Bypass</strong>: When a focused foreground application runs in exclusive fullscreen mode (e.g. 3D games or video players), Lertaro automatically bypasses all global hotkeys to avoid interrupting gameplay.</li><li><strong>Custom Process Blacklist</strong>: Add executable names under <a href="./settings/hotkeys-page.html#_3-process-blacklist"><strong>Settings → Hotkeys</strong></a> (e.g. <code>game.exe</code>) to silence hotkeys and mouse triggers while that process is focused.</li></ul>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};